    "stem": "100 80 60 40 20 0 )%( sgnitar ’stnednopseR Percent of UK Survey Respondents Who Trust People At Least Somewhat 2005 2018 2022 Year of study meet for the first time know personally Social scientists distinguish two different categories of social trust: bonding trust and bridging trust. Bonding trust refers to trust within already existing relationships (e.g., within a family), whereas bridging trust refers to trust between different groups, often involving interactions beyond one’s immediate social circle (e.g., meeting someone at a networking event). In order to evaluate these two aspects of social trust in the United Kingdom, researchers asked participants in 2005, 2018, and 2022 to rate the level of trust they felt for people they know personally and for people they are meeting for the first time. After analyzing the data from the survey responses, the researchers concluded that the level of bonding trust in the UK ______ Which choice most effectively uses data from the graph to complete the statement?",
