    "passage": "400\n300\n200\n100\n0\nsrodnoc\nfo\nrebmuN\nCalifornia Condor Populations\n2014–2020\n4 5 6 7 8 9 0\n1 1 1 1 1 1 2\n0 0 0 0 0 0 0\n2 2 2 2 2 2 2\nYear\ncaptive\nwild\nThe California Condor Recovery Program is working to protect this large, rare American vulture from extinction. The program captured 27 wild\ncondors in 1987 in order to protect and breed them. Captive birds have been reintroduced into the wild since 1992. Although the California\ncondor is still a rare species, many biologists claim that the program has been reasonably successful.",
