    "stem": "Land Area Covered by Native Flowering Plants at a Site in Antarctica Area covered in 2009 (in square Area covered in 2018 (in square Percent increase in area covered from 2009 Species meters) meters) to 2018 Deschampsia 1,230 1,576 28% antarctica Colobanthus 6.9 10.7 55% quitensis The only flowering plant species native to Antarctica, Colobanthus quitensis and Deschampsia antarctica grow in places where the earth remains free of ice for much of the year. Botanist Niccoletta Cannone wondered how the warming of Antarctica’s climate in recent years had affected these species, so she visited a site in Antarctica, first in 2009 and later in 2018, to count the number of plants growing there. Cannone found that the area of land covered by the two species had significantly expanded during the nine-year period. While both species likely benefited from warming temperatures, Colobanthus quitensis ______ Which choice most effectively uses data from the table to complete the comparison?",
    "type": "mcq",
    "options": [
      {
        "id": "A",
        "text": "suppressed the growth of Deschampsia antarctica, which covered a smaller area of land in 2018 than it had in 2009."
      },
      {
        "id": "B",
        "text": "saw a greater expansion than Deschampsia antarctica did, increasing the area of land it covered by more than half."
      },
      {
        "id": "C",
        "text": "showed a greater increase in the average size of individual plants than Deschampsia antarctica did."
      },
      {
        "id": "D",
        "text": "covered land newly freed from ice at a rate 55% faster than that of Deschampsia antarctica."
      }
    ],
    "correctAnswer": "B",
    "explanation": "Choice B is the best answer because it most effectively uses data from the table to complete the comparison of how Colobanthus quitensis benefited from warming temperatures with how Deschampsia antarctica benefited from them. The table shows the land area covered by these two plant species at a site in Antarctica. According to the table, Colobanthus quitensis increased the area it covered by 55% from 2009 to 2018, whereas Deschampsia antarctica increased the area it covered by 28% during the same period. It therefore follows that Colobanthus quitensis saw a greater expansion than Deschampsia antarctica did and that Colobanthus quitensis increased the area of land it covered by more than half.\n\nChoice A is incorrect because according to the table, Deschampsia antarctica covered 1,230 square meters of land in 2009 and 1,576 square meters of land in 2018. Deschampsia antarctica therefore covered a larger, not a smaller, area of land in 2018 than in 2009. Moreover, there’s no information in the text or the table that suggests that one species of the plant suppressed the other.\n\nChoice C is incorrect because it inaccurately describes the data in the table. The table shows the land area covered by Colobanthus quitensis and Deschampsia antarctica and the percent increase in area covered by the two species from 2009 to 2018, not the average size of individual plants belonging to the two species. The data in the table therefore can’t be used to make a comparison of the increase in individual plants’ average size.\n\nChoice D is incorrect because the table shows the land area covered by Colobanthus quitensis and Deschampsia antarctica and the percent increase in area covered by the two species from 2009 to 2018, not the rate at which the species increased the area they covered. Moreover, there’s nothing in the table or the text that suggests that the areas covered by the two species were newly freed from ice."
