    "stem": "Dated Ages of Lunar Samples from Select Missions Mission name Year Landing site Approximate age of lunar samples (billions of years) Apollo 11 1969 Mare Tranquillitatis 3.6 Apollo 15 1971 Mare Imbrium 3.3 Apollo 17 1972 Mare Serenitatis 3.8 Chang’e 5 2020 Oceanus Procellarum 2.0 The Apollo program missions were spaceflights to the moon led by the United States during the 1960s and 1970s during which astronauts collected some samples of the moon’s surface. More recently, China launched the Chang’e 5 mission, which returned additional lunar surface samples. Researchers have analyzed and dated each of the samples, concluding that the lunar samples collected during the Chang’e 5 mission are significant because ______ Which choice most effectively uses data from the table to complete the claim?",
