    "stem": "60 55 50 45 40 35 30 25 20 15 10 5 0 sremraf elameF latot fo egatnecrep a sa Percentage of Ondo State Small-Scale Farmers Who Are Female, by Main Crop Grown o o o d d d n n n O O O n ort h e ntr al s o ut h c Ondo State region cereals root crops non–root vegetables Geographer Adebayo Oluwole Eludoyin and his colleagues surveyed small-scale farmers in three locations in Ondo State, Nigeria—which has mountainous terrain in the north, an urbanized center, and coastal terrain in the south—to learn more about their practices, like the types of crops they mainly cultivated. In some regions, female farmers were found to be especially prominent in the cultivation of specific types of crops and even constituted the majority of farmers who cultivated those crops; for instance, ______ Which choice most effectively uses data from the graph to complete the example?",
    "type": "mcq",
