    "stem": "Fiber Characteristics of Mouflon, Navajo-Churro, and Spanish Merino Sheep Type of sheep Diameter of outer coat fibers (in microns) Diameter of inner coat fibers (in microns) Spanish Merino 19–24 17–21 Navajo-Churro 35 or higher 10–35 Mouflon 150 15 Domestic sheep’s wild ancestor, the mouflon, has a coarse outer coat and an inner coat of wool fiber that is finer in diameter and therefore much softer. In some domestic breeds, such as the Spanish Merino, the outer fiber is only marginally coarser than the inner, and the wool is soft overall. Thus, Merino wool is ideal for delicate garments worn against the skin. Meanwhile, the Navajo-Churro has been selected to retain the marked distinction between outer and inner fiber that the Merino has lost. Being coarser than Merino wool overall, Navajo-Churro wool yields a more durable yarn, which Diné (Navajo) weavers use in their celebrated rugs. Yet a comparison of the fiber characteristics of all three sheep reveals that ______ Which choice most effectively uses data from the table to complete the text?",
