    "stem": "60 50 40 30 20 10 0 noitubirtnoc fo egatnecreP Relative Contributions of Processes to Prokaryotic and Fungal Community Assembly in Qinghai-Tibetan Lakes v ari a bl e s e o l g e e c n ti e o o n u s s e d l i e s c p t e i o r n s al li m o i g t e a n ti i o z n i n g d n i s d p o e m r s i a n l a nt pr o c e s s m m o o o n h h fungal community prokaryotic community In a 2020 study, Jian Yang et al. examined prokaryotic and fungal microbial communities in Qinghai-Tibetan Plateau lake sediment to understand the relative contributions of various factors to community assembly, or formation. They quantified the contributions of environmental pressures (variable and homogeneous selection), dispersal limitation, homogenizing dispersal, and nondominant processes. Tolerance of environmental pressures is known to be higher in fungi than in prokaryotes, which the researchers hypothesize accounts for the finding that ______ Which choice most effectively uses data from the graph to complete the statement?",
    "type": "mcq",
    "options": [
      {
        "id": "A",
        "text": "homogenizing dispersal contributed substantially less to fungal community assembly than variable selection did."
      },
      {
        "id": "B",
        "text": "the total number of factors that contributed to community assembly was greater for prokaryotes than for fungi."
      },
      {
        "id": "C",
        "text": "variable selection contributed substantially less to fungal community assembly than to prokaryote community assembly."
      },
      {
        "id": "D",
        "text": "the contribution of homogeneous selection to community assembly was negligible for both fungi and prokaryotes."
      }
    ],
    "correctAnswer": "C",
    "explanation": "Choice C is the best answer because it most effectively uses data from the graph to complete the statement about the researchers’ hypothesis regarding a finding. The text states that the researchers attribute a certain finding about community assembly in fungi and prokaryotes to the fact that fungi have a higher tolerance for environmental pressures than do prokaryotes. This finding, then, would be explained by the fact that fungi better tolerate environmental pressures, which the text defines as including variable and homogeneous selection. According to the graph, the contribution of variable selection to community assembly was nearly 40 percent for fungi but nearly 60 percent for prokaryotes, indicating that variable selection contributed significantly less to fungal community assembly than to prokaryotic community assembly. This finding aligns with the researchers’ hypothesis: because fungi tolerate environmental pressures like variable selection better than prokaryotes do, those pressures play a smaller role in shaping fungal communities than in shaping prokaryotic communities.\n\nChoice A is incorrect. Although this comparison is supported by the graph, which shows that homogenizing dispersal’s contribution to fungal community assembly was just over 10 percent while variable selection’s contribution was just under 40 percent, this comparison doesn’t illustrate the hypothesis because it involves two factors affecting fungal community assembly. The researchers’ hypothesis specifically concerns a difference between fungi and prokaryotes (namely, fungi’s greater tolerance of environmental pressures), so a comparison that is limited to fungal community assembly doesn’t represent a finding that aligns with this hypothesis.\n\nChoice B is incorrect because it mischaracterizes the information in the graph. The graph indicates that the total number of factors that contributed to community assembly was greater for fungi than for prokaryotes: all five factors made nonzero contributions to fungal community assembly, while two factors—homogeneous selection and dispersal limitation—appear not to have contributed to prokaryotic community assembly. In addition, the overall number of factors that influence community assembly isn’t directly relevant to the researchers’ hypothesis, which addresses the effects of higher tolerance of environmental pressures among fungi in comparison to prokaryotes.\n\nChoice D is incorrect. Although the graph indicates that homogeneous selection contributed only minimally to fungal community assembly and appears not to have contributed at all to prokaryotic community assembly, this isn’t a finding that the researchers’ hypothesis would account for. The hypothesis concerns a difference between fungi and prokaryotes that is plausibly attributable to fungi’s greater tolerance of environmental pressures, which include homogeneous and variable selection. The finding that one type of environmental pressure contributed negligibly to both groups doesn’t differentiate fungi from prokaryotes and therefore doesn’t illustrate what the hypothesis is meant to explain."
