    "passage": "Data Sources for Neptune Temperature Analysis Instrument Observatory Data type Observation years TEXES (Texas Echelon Cross Echelle Spectrograph) Gemini Observatory spectroscopy 2007, 2019 T-ReCS (Thermal-Region Camera Spectrograph) Gemini Observatory infrared imaging 2007, 2010 LWS (Long Wavelength Spectrometer) Keck Observatory infrared imaging 2003 VISIR (VLT Imager and Spectrometer for mid-InfraRed) European Southern Observatory spectroscopy 2006 Julianne I. Moses and colleagues have reported that Neptune may have cooled significantly between 2003 and 2020. The team reached this conclusion by analyzing existing infrared imaging and spectroscopy data about the planet obtained from various instruments in different years.",
    "stem": "Of the team’s sources listed in the table, the earliest example of spectroscopy data included in the analysis was obtained in ______ Which choice most effectively uses data from the table to complete the text?",
