    "passage": "0.25\n0.20\n0.15\n0.10\n0.05\n0\nhtworg\nlaidaR\n)raey\nrep\nsretemitnec(\nModeled Radial Growth of\nSugar Maple Trees\nurr e\nnt\nh\na n g\ne\nh\na n g\ne\nc\ne\nc\ne\nc\nat m\nm o\nd\ner\ne\nxtr\ne\nClimate scenario\nwith nitrogen\nwithout nitrogen\nInés Ibáñez and colleagues studied a forest site in which some sugar maple trees receive periodic fertilization with nitrogen to mimic the broader\ntrend of increasing anthropogenic nitrogen deposition in soil. Ibáñez and colleagues modeled the radial growth of the trees with and without\nnitrogen fertilization under three different climate scenarios (the current climate, moderate change, and extreme change). Although they found\nthat climate change would negatively affect growth, they concluded that anthropogenic nitrogen deposition could more than offset that effect\nprovided that change is moderate rather than extreme.",
