    "stem": "Effects of Mycorrhizal Fungi on 3 Plant Species Plant Mycorrhizal Average mass of plants grown in soil containing Average mass of plants grown in soil treated to species host mycorrhizal fungi (in grams) kill fungi (in grams) Corn yes 15.1 3.8 Marigold yes 10.2 2.4 Broccoli no 7.5 7 Mycorrhizal fungi in soil benefits many plants, substantially increasing the mass of some. A student conducted an experiment to illustrate this effect. The student chose three plant species for the experiment, including two that are mycorrhizal hosts (species known to benefit from mycorrhizal fungi) and one nonmycorrhizal species (a species that doesn’t benefit from and may even be harmed by mycorrhizal fungi). The student then grew several plants from each species both in soil containing mycorrhizal fungi and in soil that had been treated to kill mycorrhizal and other fungi. After several weeks, the student measured the plants’ average mass and was surprised to discover that ______ Which choice most effectively uses data from the table to complete the statement?",
