    "subtopicId": "evidence-quantitative",
    "subtopic": "Command of evidence (quantitative / graphs)",
    "difficulty": "hard",
    "passage": "Mean Time (in Seconds) Spent per Flower for Four Pollinator Genera Pollinator Seconds per intact pin Seconds per damaged pin Seconds per intact thrum Seconds per damaged thrum genus flower flower flower flower Habropoda 2.7 5.4 4.1 9.5 Osmia 5.2 8.2 7.1 8.3 Pierid 2.6 4.0 2.4 1.9 Xylocopa 2.3 2.8 2.5 2.2 To study how floral damage affects the behavior of pollinators, such as bees, a team of researchers punched holes in the floral tissue of flowers from the vine yellow jessamine (Gelsemium sempervirens), a plant that produces flowers that have either a long pistil and a short stamen (pin morphs) or a short pistil and a long stamen (thrum morphs). The researchers then compared the time different insect pollinators spent visiting intact pin and thrum flowers to the time such pollinators spent visiting the artificially damaged pin and thrum flowers. The researchers concluded that the effect of floral damage on time spent per flower varied by both floral morph and the genus of the pollinator.",
    "stem": "Which choice best describes data from the table that support the researchers’ conclusion?",
    "type": "mcq",
    "options": [
      {
        "id": "A",
        "text": "For pin flowers, damage led to longer times per flower in all pollinator genera, whereas for thrum flowers, damage led to longer times per flower only in Habropoda and Osmia."
      },
      {
        "id": "B",
        "text": "Compared with pollinators belonging to the genus Osmia, pollinators belonging to the genus Xylocopa spent less time on damaged pin flowers but more time on damaged thrum flowers."
      },
      {
        "id": "C",
        "text": "Damage led to shorter times per thrum flower in three pollinator genera (Osmia, Pierid, and Xylocopa), whereas it led to longer times per thrum flower in one pollinator genus (Habropoda)."
      },
      {
        "id": "D",
        "text": "Pollinators belonging to the genus Habropoda spent 2.7 seconds on intact pin flowers and 4.1 seconds on intact thrum flowers."
      }
    ],
    "correctAnswer": "A",
    "explanation": "Choice A is the best answer because it describes data from the table that support the researchers’ conclusion that the effect of floral damage on time spent per flower varied by both floral morph and the genus of the pollinator. The table presents the average time pollinators spent per floral morph. The data in the table shows that for pin flowers, the average time spent per flower by all pollinator genera was higher for flowers that had been artificially damaged than for intact flowers. By contrast, for thrum flowers, the difference in time spent on intact and damaged flowers is seen for only some pollinator genera. This supports the researchers’ conclusion that both floral morph and the genus of the pollinator are factors involved in the effect that floral damage has on time pollinators spend per flower.\n\nChoice B is incorrect. The table shows that pollinators belonging to the genus Xylocopa spent less time on both damaged pin flowers and damaged thrum flowers than pollinators belonging to the genus Osmia did.\n\nChoice C is incorrect. The table shows that the artificial damage to the thrum flowers led to shorter average times spent by pollinators on those flowers for only two of the four pollinator genera represented in the table, not three. Furthermore, this choice doesn’t address the effect the artificial damage had on pin flowers; thus, even if accurate, this evidence doesn’t support the researchers’ conclusion that both floral morph and pollinator genus affect time spent per flower when a flower has been damaged.\n\nChoice D is incorrect. While this statement is true based on the information in the table, it doesn’t provide evidence that supports the researchers’ conclusion that the effect of floral damage on time spent per flower varied by both floral morph and the genus of the pollinator because this choice provides information only about how much time one pollinator genus spent on intact flowers."
