    "passage": "Correlations Between Congestion Ratings and Features of the Crowd in Raters’ Immediate Vicinity Crowd feature Before obstacle After obstacle Overall Density 0.8592 0.7308 0.7447 Velocity −0.9357 −0.9518 −0.8587 Researcher Xiaolu Jia and colleagues monitored individuals’ velocity and the surrounding crowd density as a group of study participants walked through a space and navigated around an obstacle. Participants rated how congested it seemed before the obstacle, after the obstacle, and overall, and the researchers correlated those ratings with velocity and density. (Correlations range from −1 to 1, with greater distance from 0 indicating greater strength). The researchers concluded that the correlations with velocity are stronger than those with density.",
