    "correctAnswer": "D",
    "explanation": "Choice D is the best answer. The researchers concluded that as we approach maximum plausible surface temperatures, there will be a larger percentage of sites where thermal pollution could contribute to meeting home heating needs. By showing that only a small percentage of homes can currently use thermal pollution for home heating, and that this percentage would grow much larger at maximum plausible surface temperatures, this choice supports the researchers’ conclusion.\n\nChoice A is incorrect. We do not know how many sites could have all (i.e., 100%) of their local heating needs met by thermal pollution, as the graph only classifies sites by whether \"0%,\" \"Up to 25%,\" and \"More than 25%\" of heating needs could be met.\n\nChoice B is incorrect. The graph is not depicting need for supplemental heating from thermal pollution, but rather potential to use thermal pollution for supplemental heating.\n\nChoice C is incorrect. The graph indicates that, at current surface temperatures, less than 10% of sites can meet 25% of local home heating needs and that more than 80% of sites cannot meet any local home heating needs."
