    "passage": "550\n500\n450\n400\n350\n300\n250\n200\n150\n100\n50\n0\n)smarg(\nthgieW\nWeight of Three Aerial Robots\nRobot\nUltra-Fast Robot Hand\nPermanent Magnet Hand\nYale Model T\nAerial robots vary considerably in their holding force; the Ultra-Fast Robot Hand, for example, has a holding force of 56 newtons, more than twice\nthat of the Permanent Magnet Hand and more than four times that of the Yale Model T. Since an aerial robot must lift its own weight along with\nits cargo, engineer Jiawei Meng and colleagues used a ratio of each robot’s holding force to the robot’s weight to calculate payload capacity, with\nhigher ratios corresponding to greater capacity, concluding that the Ultra-Fast Robot Hand has a higher payload capacity than the Yale Model T.",
