    "passage": "30\n25\n20\n15\n10\n5\n0\n)slacsapagem(\nhtgnerts\nevisserpmoC\nCompressive Strength of\nMortar Mixtures After Curing\n%\nS S\nA)\n%\nS S\nA\n%\nS S\nA\n%\nS S\nA\nol\n( 0 1 0 2 0 4 0\nntr\no\nc\nMixture\nday 7 day 28\nMollusk shells are mainly composed of calcium carbonate, a chemical compound used in mortar and other construction materials. A research\nteam led by Ariane da Silva Cardoso investigated pulverizing discarded Sururu mussel shells to create a substitute for fine aggregates (such as\nsand) in mortar mixtures. The team prepared mixtures with Sururu shell aggregate (SSA) replacing varying percentages of sand and then tested\nthe mortars’ compressive strength on days 7 and 28 of curing. Based on their findings, the team recommended SSA substitution in relatively\nsmall proportions to avoid compromising strength.",
