    "passage": "3.0\n2.5\n2.0\n1.5\n1.0\n0.5\n0\nfo\negatnecrep\negarevA\nepahs\nyb\nsllec\nlanogaxehnon\nPercentage of Nonhexagonal Cells in\nHives of Three Honeybee Species\ne e e\ne e e\nb b b\ny y y\ne e e\nn n n\no o o\nh h h\nk\nd\nw\narf\nd\nw\narf\nw\ne\nst\ner\nn\nc\na\nbl\nSpecies\n5-sided cells\n7-sided cells\n8-sided cells\nHoneybee hives consist mainly of hexagonal (six-sided) units called cells, in which queens lay eggs. Hexagonal cells for eggs that develop into\nnonreproductive workers are smaller than those for eggs that develop into reproductive drones, though the size difference varies by species.",
    "stem": "Difference in cell size results in a construction problem—it’s hard to neatly connect sections of small cells to sections of large cells—that worsens as the difference increases. To fill in gaps between the sections when building a hive, bees rely on cells that have more or fewer than six sides. A student studying beehive structure consults data on three species, concluding that ______ Which choice most effectively uses data from the graph to complete the student’s conclusion?",
    "type": "mcq",
